export interface ReferenceOnlyProject {
  id: number;
  projectKey: string;
  category: string;
  name: string;
  sourceSheet: string;
  /** @nullable */
  excelRow: number | null;
  sourceRows: ReferenceOnlySourceRow[];
  relatedRecords: ReferenceOnlyRelatedRecord[];
}

export interface ReferenceOnlyCatalog {
  summary: ReferenceOnlySummary;
  records: ReferenceOnlyProject[];
  refreshedAt: string;
}

export interface DatabaseColumn {
  name: string;
  dataType: string;
  nullable: boolean;
  primaryKey: boolean;
  identity: boolean;
  computed: boolean;
  editable: boolean;
  /** @nullable */
  maxLength: number | null;
  precision: number;
  scale: number;
}

export interface DatabaseTable {
  schemaName: string;
  tableName: string;
  recordCount: number;
  columns: DatabaseColumn[];
}

export interface DatabaseCatalog {
  tables: DatabaseTable[];
  refreshedAt: string;
}

export interface DatabaseRowsQuery {
  /** @minimum 1 */
  page: number;
  /**
     * @minimum 1
     * @maximum 100
     */
  pageSize: number;
  /** @maxLength 200 */
  search?: string;
}

export type DatabaseRowsRowsItem = { [key: string]: unknown };

export interface DatabaseRows {
  schemaName: string;
  tableName: string;
  columns: DatabaseColumn[];
  rows: DatabaseRowsRowsItem[];
  total: number;
  page: number;
  pageSize: number;
}

/**
 * @nullable
 */
export type DatabaseScalar = string | number | boolean | null;

export type DatabaseRowUpdateKey = {[key: string]: DatabaseScalar | null};

export type DatabaseRowUpdateValues = {[key: string]: DatabaseScalar | null};

export interface DatabaseRowUpdate {
  key: DatabaseRowUpdateKey;
  values: DatabaseRowUpdateValues;
}

export interface DatabaseRowUpdateResponse {
  updated: boolean;
  schemaName: string;
  tableName: string;
}

